(function(){'use strict';const $=id=>document.getElementById(id);let storage;try{storage=localStorage}catch(e){storage={getItem:()=>null,setItem:()=>{throw e}}}let settings=obAccessibility.load(storage);function render(){obAccessibility.apply(document,settings);for(const k of ['palette','text','pointer'])$(k).value=settings[k];$('pointer-preview').src='pointer-'+({normal:32,large:48,largest:64})[settings.pointer]+'.svg'}for(const key of ['palette','text','pointer'])$(key).addEventListener('change',()=>{settings[key]=$(key).value;render();$('status').textContent='Preview changed. Save to keep it.'});$('save').addEventListener('click',async()=>{try{settings=obAccessibility.save(storage,settings);$('status').textContent='Saved for this app.';if(window.obAccessibilityHost?.apply){const result=await obAccessibilityHost.apply({...settings});$('status').textContent=result?.accepted?'Saved and applied by Omni.':'Saved here; the browser setting was not applied.'}}catch(e){$('status').textContent='Settings could not be saved. Your preview still works.'}});$('reset').addEventListener('click',()=>{settings=obAccessibility.normalize(null);render();$('status').textContent='Default preview restored. Save to keep it.'});$('sample-button').addEventListener('click',()=>{$('status').textContent='Focus and selection are working.'});document.addEventListener('focusin',e=>document.querySelectorAll('.pad-focus').forEach(x=>{if(x!==e.target)x.classList.remove('pad-focus')}));render()})();
